#include "nova64/cpu/cp0.hpp"
namespace nova64 { uint64_t Cp0::read(unsigned r)const{switch(r){case 0:return index_;case 1:return random();case 2:return entrylo0_;case 3:return entrylo1_;case 4:return context_;case 5:return page_mask_;case 6:return wired_;case 8:return badvaddr_;case 9:return count_;case 10:return entryhi_;case 11:return compare_;case 12:return status_;case 13:return cause_;case 14:return epc_;case 15:return prid_;case 18:return 0;case 20:return xcontext_;default:return 0;}} void Cp0::write(unsigned r,uint64_t v){uint32_t x=v;switch(r){case 0:index_=x&0x8000001f;break;case 2:entrylo0_=x;break;case 3:entrylo1_=x;break;case 4:context_=x&0xff800000;break;case 5:page_mask_=x&0x01ffe000;break;case 6:wired_=x&31;break;case 9:count_=x;break;case 10:entryhi_=x;break;case 11:compare_=x;cause_&=~(1u<<15);break;case 12:status_=x;break;case 13:cause_=(cause_&0x0000ff00)|(x&0xffff00ff);break;case 14:epc_=x;break;case 20:xcontext_=x;break;default:break;}} void Cp0::tick(uint32_t n){uint32_t old=count_;count_+=n;if(compare_&&count_<old)cause_|=1u<<15;} void Cp0::raise(ExceptionCode c,uint64_t bad,uint64_t pc,bool delay){badvaddr_=uint32_t(bad);epc_=uint32_t(delay?pc-4:pc);cause_=(cause_&~0x7c)|(uint32_t(c)<<2)|(delay?1u<<31:0);status_=(status_&~0x3f)|((status_&0xf)<<2);status_|=1u<<1;} void Cp0::eret(){status_=(status_&~0x3f)|((status_>>2)&0xf);status_&=~2u;} bool Cp0::interrupt_pending()const{return (status_&1)&&((status_&cause_&0xff00)!=0);}}
